fun {α} [DecidableEq α] s1 s2 =>
  (have m := s1.length;
    have n := s2.length;
    have dp := Array.replicate (m + 1) (Array.replicate (n + 1) 0);
    do
    let r ←
      forIn { stop := m + 1, step_pos := Nat.zero_lt_one } dp fun i r =>
          have dp := r;
          have dp := dp.set! i (dp[i]!.set! 0 i);
