          pure PUnit.unit
          pure (ForInStep.yield dp)
    have dp : Array (Array ℕ) := r
    let r ←
      forIn { stop := n + 1, step_pos := Nat.zero_lt_one } dp fun j r =>
          have dp := r;
          have dp := dp.set! 0 (dp[0]!.set! j j);
          do
          pure PUnit.unit
          pure (ForInStep.yield dp)
    have dp : Array (Array ℕ) := r
    let r ←
      forIn { start := 1, stop := m + 1, step_pos := Nat.zero_lt_one } dp fun i r =>
          have dp := r;
          do
          let r ←
            forIn { start := 1, stop := n + 1, step_pos := Nat.zero_lt_one } dp fun j r =>
                have dp := r;
